def f(input_val):
    x = [input_val & 0xFF, (input_val >> 8) & 0xFF, (input_val >> 16) & 0xFF, (input_val >> 24) & 0xFF]
    y2 = g(x[3] ^ x[2], x[1] ^ x[0], 1)
    y3 = g(x[3], y2, 0)
    y1 = g(x[1] ^ x[0], y2, 0)
    y0 = g(x[0], y1, 1)
    return y0 | (y1 << 8) | (y2 << 16) | (y3 << 24)

def expand(key):
