def encrypt_val(plaintext, keys):
    left = (plaintext >> 32) & 0xFFFFFFFF
    right = plaintext & 0xFFFFFFFF
    right ^= left
    for k in keys:
        m = f(right ^ k)
        right, left = left ^ m, right
    left ^= right
